import { Store } from "@/Store"
import { Legacy } from "@/Model"
import {
  DeserializerInterface,
  SerializerInterface,
  SerializedLegacy,
} from "@/Serializer"

const KEY: string = "legacies"
export default class LegacyRepository {
  constructor(
    private readonly store: Store,
    private readonly serializer: SerializerInterface,
    private readonly deserializer: DeserializerInterface,
  ) {}

  public findAll(): Legacy[] {
    return (this.store.get<SerializedLegacy[]>(KEY) ?? []).map(
      (legacy: SerializedLegacy): Legacy =>
        this.deserializer.deserialize(legacy)!,
    )
  }

  public save(legacy: Legacy): void {
    let all: Legacy[] = this.findAll()
    const i: number = all.findIndex((l: Legacy): boolean => l.is(legacy))

    if (i >= 0) {
      all = [...all.slice(0, i), legacy, ...all.slice(i + 1)]
    } else {
      all.push(legacy)
    }

    this.store.set<SerializedLegacy[]>(
      KEY,
      all.map(
        (l: Legacy): SerializedLegacy => this.serializer.serialize(l)!,
        this,
      ),
    )
  }

  public find(id: string): Legacy | null {
    const all: Legacy[] = this.findAll()
    const l: Legacy | undefined = all.find((l: Legacy): boolean => l.id === id)

    return l ?? null
  }

  public delete(legacy: Legacy): void {
    const all: Legacy[] = this.findAll().filter(
      (l: Legacy): boolean => !l.is(legacy),
    )

    this.store.set<SerializedLegacy[]>(
      KEY,
      all.map((l: Legacy): SerializedLegacy => this.serializer.serialize(l)!),
    )
  }
}
